sql:
-- 1. Reset tabel cache host yang terblokir
FLUSH HOSTS;

-- 2. Tingkatkan toleransi error koneksi agar tidak mudah terblokir (default: 100)
SET GLOBAL max_connect_errors = 10000;

-- 3. Verifikasi nilai saat ini
SHOW GLOBAL VARIABLES LIKE 'max_connect_errors';

-- Cek batas koneksi saat ini
SHOW VARIABLES LIKE 'max_connections';

-- Cek jumlah koneksi tertinggi yang pernah terjadi (peak)
SHOW STATUS LIKE 'Max_used_connections';

-- Naikkan batas koneksi (misal ke 500 koneksi)
SET GLOBAL max_connections = 500;

SELECT VERSION() AS mysql_version;

SELECT @@global.sql_mode AS global_sql_mode,
       @@session.sql_mode AS session_sql_mode;
